CREATE OR REPLACE FUNCTION public.create_community_chat_group(p_id uuid,p_community_id uuid,p_name text,p_description text DEFAULT '',p_visibility text DEFAULT 'public',p_countries_enabled boolean DEFAULT NULL,p_allowed_countries uuid[] DEFAULT NULL,p_cities_enabled boolean DEFAULT NULL,p_allowed_cities uuid[] DEFAULT NULL,p_certification_required boolean DEFAULT NULL,p_gender_restriction genre_enum DEFAULT NULL,p_age_min integer DEFAULT NULL,p_age_max integer DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_row public.community_salons; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Utilisateur non authentifié'; END IF; IF p_name IS NULL OR length(trim(p_name))<2 OR length(trim(p_name))>80 THEN RAISE EXCEPTION 'Nom du groupe invalide'; END IF; IF p_visibility NOT IN ('public','private') THEN RAISE EXCEPTION 'Visibilité invalide'; END IF; v_row:=public.create_community_salon(p_id,p_community_id,trim(p_name),false,p_countries_enabled,p_allowed_countries,p_cities_enabled,p_allowed_cities,p_certification_required,p_gender_restriction,p_age_min,p_age_max); UPDATE public.community_salons SET visibility=p_visibility,description=COALESCE(trim(p_description),'') WHERE id=p_id; INSERT INTO public.community_salon_members(salon_id,user_id,role) VALUES(p_id,auth.uid(),'owner') ON CONFLICT(salon_id,user_id) DO NOTHING; RETURN p_id; END; $$; CREATE OR REPLACE FUNCTION public.request_community_chat_group_access(p_salon_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_salon public.community_salons; v_uid uuid:=auth.uid(); v_status text; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Utilisateur non authentifié'; END IF; SELECT * INTO v_salon FROM public.community_salons WHERE id=p_salon_id; IF NOT FOUND THEN RAISE EXCEPTION 'Groupe introuvable'; END IF; IF NOT public.is_community_member(v_salon.community_id) THEN RAISE EXCEPTION 'Vous devez d’abord rejoindre la communauté'; END IF; IF NOT public.check_salon_eligibility(p_salon_id,v_uid) THEN RAISE EXCEPTION 'Vous ne remplissez pas les conditions d’accès à ce groupe'; END IF; IF v_salon.visibility='public' THEN INSERT INTO public.community_salon_members(salon_id,user_id,role) VALUES(p_salon_id,v_uid,'member') ON CONFLICT DO NOTHING; RETURN jsonb_build_object('status','accepted','salon_id',p_salon_id); END IF; IF v_salon.created_by=v_uid OR EXISTS(SELECT 1 FROM public.community_salon_members WHERE salon_id=p_salon_id AND user_id=v_uid) THEN RETURN jsonb_build_object('status','accepted','salon_id',p_salon_id); END IF; INSERT INTO public.community_salon_join_requests(salon_id,user_id,status,requested_at,reviewed_at,reviewed_by) VALUES(p_salon_id,v_uid,'pending',now(),NULL,NULL) ON CONFLICT(salon_id,user_id) DO UPDATE SET status='pending',requested_at=now(),reviewed_at=NULL,reviewed_by=NULL RETURNING status INTO v_status; RETURN jsonb_build_object('status',v_status,'salon_id',p_salon_id); END; $$; CREATE OR REPLACE FUNCTION public.review_community_chat_group_request(p_request_id uuid,p_decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_request public.community_salon_join_requests; v_salon public.community_salons; BEGIN IF auth.uid() IS NULL OR p_decision NOT IN ('accepted','rejected') THEN RAISE EXCEPTION 'Requête invalide'; END IF; SELECT * INTO v_request FROM public.community_salon_join_requests WHERE id=p_request_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Demande introuvable'; END IF; SELECT * INTO v_salon FROM public.community_salons WHERE id=v_request.salon_id; IF v_salon.created_by<>auth.uid() AND NOT public.community_can(v_salon.community_id,'can_create_salon') THEN RAISE EXCEPTION 'Action non autorisée'; END IF; IF v_request.status<>'pending' THEN RAISE EXCEPTION 'Cette demande a déjà été traitée'; END IF; IF p_decision='accepted' THEN IF NOT public.is_community_member(v_salon.community_id) OR NOT public.check_salon_eligibility(v_salon.id,v_request.user_id) THEN RAISE EXCEPTION 'Le demandeur ne remplit plus les conditions d’accès'; END IF; INSERT INTO public.community_salon_members(salon_id,user_id,role) VALUES(v_salon.id,v_request.user_id,'member') ON CONFLICT DO NOTHING; END IF; UPDATE public.community_salon_join_requests SET status=p_decision,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=p_request_id; RETURN jsonb_build_object('status',p_decision,'request_id',p_request_id); END; $$; CREATE OR REPLACE FUNCTION public.get_community_chat_group_requests(p_salon_id uuid) RETURNS TABLE(request_id uuid,user_id uuid,username text,photo_url text,requested_at timestamptz,status text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_salon public.community_salons; BEGIN SELECT * INTO v_salon FROM public.community_salons WHERE id=p_salon_id; IF NOT FOUND OR auth.uid() IS NULL OR (v_salon.created_by<>auth.uid() AND NOT public.community_can(v_salon.community_id,'can_create_salon')) THEN RAISE EXCEPTION 'Action non autorisée'; END IF; RETURN QUERY SELECT r.id,r.user_id,p.username,p.photo_url,r.requested_at,r.status FROM public.community_salon_join_requests r LEFT JOIN public.user_profiles p ON p.user_id=r.user_id WHERE r.salon_id=p_salon_id AND r.status='pending' ORDER BY r.requested_at ASC; END; $$; GRANT EXECUTE ON FUNCTION public.create_community_chat_group(uuid,uuid,text,text,text,boolean,uuid[],boolean,uuid[],boolean,genre_enum,integer,integer) TO authenticated; GRANT EXECUTE ON FUNCTION public.request_community_chat_group_access(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.review_community_chat_group_request(uuid,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.get_community_chat_group_requests(uuid) TO authenticated;